// src/middlewares/auth.ts
import httpStatus3 from "http-status";
var auth = (...requiredRoles) => {
  return catchAsync(
    async (req, res, next) => {
      const token = req.cookies.accessToken ? req.cookies.accessToken : req.headers.authorization?.startsWith("Bearer ") ? req.headers.authorization?.split(" ")[1] : req.headers.authorization;
      if (!token) {
        throw new Error("You are not logged in. Please log in to access this resource");
      }
      const verifiedToken = jwtUtils.verifyToken(token, config_default.jwt_access_secret);
      if (!verifiedToken.success) {
        throw new Error(verifiedToken.error);
      }
      ;
      const { id, name, email, role } = verifiedToken.data;
      if (requiredRoles.length && !requiredRoles.includes(role)) {
        return sendResposne(res, {
          success: false,
          statusCode: httpStatus3.FORBIDDEN,
          message: "Forbidden: You do not have permission to access this resource.",
          data: null
        });
      }
      ;
      const user = await prisma.user.findUnique({
        where: {
          id,
          email,
          name,
          role
        }
      });
      if (!user) {
        throw new Error("User not found. Please log in again.");
      }
      ;
      if (user.isActive === UserStatus.BANNED) {
        throw new Error("Your account has been banned by the administrator.");
      }
      req.user = {
        email,
        name,
        id,
        role
      };
      next();
    }
  );
};

