// src/lib/stripe.ts
import Stripe from "stripe";
var stripe = new Stripe(config_default.stripe_secret_key);

// src/modules/payment/payment.service.ts
import axios from "axios";
var initiatepayment = async (userId, payload) => {
  const { orderId, provider, transactionId } = payload;
  if (!orderId || !provider) {
    throw new Error("orderId and provider are required");
  }
  const order = await prisma.order.findUniqueOrThrow({
    where: { id: orderId },
    include: { payment: true }
  });
  if (order.userId !== userId) {
    throw new Error("Forbidden: You can only initiate payment for your own order");
  }
  if (order.payment) {
    throw new Error("A payment record already exists for this order");
  }
  const payment = await prisma.payment.create({
    data: {
      orderId,
      amount: order.totalAmount,
      provider: provider.toUpperCase(),
      transactionId: transactionId || null,
      status: PaymentStatus.PENDING
    },
    include: {
      order: {
        select: {
          id: true,
          status: true,
          totalAmount: true,
          deliveryZone: true,
          deliveryAddress: true
        }
      }
    }
  });
  return {
    ...payment,
    amount: Number(payment.amount)
  };
};
var updatePaymentStatus = async (paymentId, payload) => {
  const { status, transactionId } = payload;
  const existingPayment = await prisma.payment.findUniqueOrThrow({
    where: { id: paymentId },
    include: { order: true }
  });
  const result = await prisma.$transaction(async (tx) => {
    const updatedPayment = await tx.payment.update({
      where: { id: paymentId },
      data: {
        status,
        ...transactionId && { transactionId }
      }
    });
    if (status === PaymentStatus.PAID && existingPayment.order.status === OrderStatus.OUT_FOR_DELIVERY) {
      await tx.order.update({
        where: { id: existingPayment.orderId },
        data: {
          status: OrderStatus.DELIVERED
        }
      });
    }
    return updatedPayment;
  });
  return {
    ...result,
    amount: Number(result.amount)
  };
};
var getPaymentByOrderId = async (orderId, userId, role) => {
  const payment = await prisma.payment.findUniqueOrThrow({
    where: { orderId },
    include: {
      order: {
        select: {
          id: true,
          userId: true,
          status: true,
          totalAmount: true
        }
      }
    }
  });
  if (role === Role.CUSTOMER && payment.order.userId !== userId) {
    throw new Error("Forbidden: You can only view payment details for your own order");
  }
  return {
    ...payment,
    amount: Number(payment.amount)
  };
};
var getRevenueSummary = async () => {
  const totalPaidAggregate = await prisma.payment.aggregate({
    where: {
      status: PaymentStatus.PAID
    },
    _sum: {
      amount: true
    },
    _count: {
      id: true
    }
  });
  const pendingAggregate = await prisma.payment.aggregate({
    where: {
      status: PaymentStatus.PENDING
    },
    _sum: {
      amount: true
    },
    _count: {
      id: true
    }
  });
  const providerBreakdown = await prisma.payment.groupBy({
    by: ["provider"],
    where: {
      status: PaymentStatus.PAID
    },
    _sum: {
      amount: true
    },
    _count: {
      id: true
    }
  });
  const statusBreakdown = await prisma.payment.groupBy({
    by: ["status"],
    _sum: {
      amount: true
    },
    _count: {
      id: true
    }
  });
  return {
    totalRevenue: Number(totalPaidAggregate._sum.amount || 0),
    totalCompletedTransactions: totalPaidAggregate._count.id,
    pendingRevenue: Number(pendingAggregate._sum.amount || 0),
    pendingTransactions: pendingAggregate._count.id,
    byProvider: providerBreakdown.map((item) => ({
      provider: item.provider,
      totalAmount: Number(item._sum.amount || 0),
      transactionCount: item._count.id
    })),
    byStatus: statusBreakdown.map((item) => ({
      status: item.status,
      totalAmount: Number(item._sum.amount || 0),
      count: item._count.id
    }))
  };
};
var createStripeCheckoutSession = async (userId, orderId) => {
  const order = await prisma.order.findUniqueOrThrow({
    where: { id: orderId },
    include: {
      items: {
        include: {
          menuItem: true
        }
      },
      user: {
        select: {
          email: true
        }
      },
      payment: true
    }
  });
  if (order.userId !== userId) {
    throw new Error("Forbidden: You can only pay for your own order");
  }
  ;
  if (order.payment?.status === PaymentStatus.PAID) {
    throw new Error("This order has already been paid");
  }
  ;
  const lineItems = order.items.map((item) => ({
    price_data: {
      currency: "bdt",
      product_data: {
        name: item.menuItem.name,
        images: item.menuItem.imageUrl ? [item.menuItem.imageUrl] : []
      },
      unit_amount: Math.round(Number(item.unitPrice) * 100)
    },
    quantity: item.quantity
  }));
  lineItems.push({
    price_data: {
      currency: "bdt",
      product_data: {
        name: "DIU Campus Delivery Fee",
        images: []
      },
      unit_amount: 20 * 100
    },
    quantity: 1
  });
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    customer_email: order.user.email,
    client_reference_id: orderId,
    line_items: lineItems,
    metadata: {
      orderId,
      userId
    },
    success_url: `${config_default.app_url}/payment?success=true&sessionId={CHECKOUT_SESSION_ID}`,
    cancel_url: `${config_default.app_url}/payment?success=false&orderId=${orderId}`
  });
  await prisma.payment.upsert({
    where: { orderId: order.id },
    create: {
      orderId: order.id,
      amount: order.totalAmount,
      provider: "STRIPE",
      status: PaymentStatus.PENDING,
      transactionId: session.id
    },
    update: {
      provider: "STRIPE",
      amount: order.totalAmount,
      status: PaymentStatus.PENDING,
      transactionId: session.id
    }
  });
  return {
    paymentUrl: session.url,
    sessionId: session.id
  };
};
var handleStripeWebhook = async (payload, signature) => {
  const webhookSecret = config_default.stripe_webhook_secret;
  if (!webhookSecret) {
    throw new Error("STRIPE_WEBHOOK_SECRET is not configured in .env");
  }
  const event = stripe.webhooks.constructEvent(payload, signature, webhookSecret);
  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const orderId = session.metadata?.orderId;
    const paymentIntentId = session.payment_intent || session.id;
    if (orderId) {
      await prisma.$transaction(async (tx) => {
        await tx.payment.update({
          where: { orderId },
          data: {
            status: PaymentStatus.PAID,
            transactionId: paymentIntentId
          }
        });
      });
    }
  }
  return { received: true };
};
var initSSLCommerzPayment = async (userId, orderId) => {
  const order = await prisma.order.findUniqueOrThrow({
    where: { id: orderId },
    include: {
      items: {
        include: {
          menuItem: true
        }
      },
      user: {
        select: {
          name: true,
          email: true
        }
      },
      payment: true
    }
  });
  if (order.userId !== userId) {
    throw new Error("Forbidden: You can only pay for your own order");
  }
  if (order.payment?.status === PaymentStatus.PAID) {
    throw new Error("This order has already been paid");
  }
  const transactionId = `SSL-${order.id.slice(-6)}-${Date.now()}`;
  const sslPayload = new URLSearchParams({
    store_id: config_default.ssl_store_id,
    store_passwd: config_default.ssl_store_pass,
    total_amount: Number(order.totalAmount).toFixed(2),
    currency: "BDT",
    tran_id: transactionId,
    // SSLCommerz sends a POST request to these backend endpoints upon completion
    success_url: `${config_default.backend_url}/payment/sslcommerz/success`,
    fail_url: `${config_default.backend_url}/payment/sslcommerz/fail`,
    cancel_url: `${config_default.backend_url}/payment/sslcommerz/cancel`,
    ipn_url: `${config_default.backend_url}/payment/sslcommerz/ipn`,
    shipping_method: "Courier",
    product_name: order.items.map((i) => i.menuItem.name).join(", "),
    product_category: "Fast Food",
    product_profile: "general",
    cus_name: order.user.name || "DIU Customer",
    cus_email: order.user.email,
    cus_add1: order.deliveryAddress,
    cus_city: "Dhaka",
    cus_state: "Dhaka",
    cus_postcode: "1341",
    cus_country: "Bangladesh",
    cus_phone: order.contactPhone,
    ship_name: order.user.name || "DIU Customer",
    ship_add1: order.deliveryAddress,
    ship_city: "Dhaka",
    ship_state: "Dhaka",
    ship_postcode: "1341",
    ship_country: "Bangladesh",
    value_a: order.id
    // Pass orderId in custom field value_a
  });
  const response = await axios.post(config_default.ssl_payment_api, sslPayload.toString(), {
    headers: {
      "Content-Type": "application/x-www-form-urlencoded"
    }
  });
  if (response.data?.status !== "SUCCESS") {
    throw new Error(
      `SSLCommerz Session Failed: ${response.data?.failedreason || "Unknown error"}`
    );
  }
  await prisma.payment.upsert({
    where: { orderId: order.id },
    create: {
      orderId: order.id,
      amount: order.totalAmount,
      provider: "SSLCOMMERZ",
      status: PaymentStatus.PENDING,
      transactionId
    },
    update: {
      provider: "SSLCOMMERZ",
      amount: order.totalAmount,
      status: PaymentStatus.PENDING,
      transactionId
    }
  });
  return {
    paymentUrl: response.data.GatewayPageURL,
    transactionId
  };
};
var validateSSLCommerzSuccess = async (payload) => {
  const { val_id, tran_id } = payload;
  if (!val_id) {
    throw new Error("Validation ID (val_id) is missing from SSLCommerz callback");
  }
  const validationUrl = `${config_default.ssl_validation_api}?val_id=${val_id}&store_id=${config_default.ssl_store_id}&store_passwd=${config_default.ssl_store_pass}&format=json`;
  const response = await axios.get(validationUrl);
  const data = response.data;
  if (data.status !== "VALID" && data.status !== "VALIDATED") {
    throw new Error("SSLCommerz payment validation failed");
  }
  const existingPayment = await prisma.payment.findUnique({
    where: { transactionId: tran_id }
  });
  if (!existingPayment) {
    throw new Error(`Payment record not found for tran_id: ${tran_id}`);
  }
  await prisma.$transaction(async (tx) => {
    await tx.payment.update({
      where: { id: existingPayment.id },
      data: {
        status: PaymentStatus.PAID
      }
    });
    await tx.order.update({
      where: { id: existingPayment.orderId },
      data: {
        status: OrderStatus.PREPARING
      }
    });
  });
  return {
    orderId: existingPayment.orderId,
    transactionId: tran_id
  };
};
var handleSSLCommerzFailOrCancel = async (payload) => {
  const { tran_id } = payload;
  if (tran_id) {
    await prisma.payment.updateMany({
      where: {
        transactionId: tran_id,
        status: PaymentStatus.PENDING
      },
      data: {
        status: PaymentStatus.FAILED
      }
    });
  }
  return { transactionId: tran_id };
};
